    71→export {
    72→  chunkDocument,
    73→  indexDocument,
    74→  indexDocuments,
    75→  removeDocument,
    76→  updateDocument,
    77→  getKnowledgeBaseStats,
    78→  clearKnowledgeBase,
    79→  createKnowledgeDocument,
    80→  validateKnowledgeDocument,
    81→  estimateDocumentStorage,
    82→} from './knowledge-base';
    83→
    84→// Retrieval exports
    85→export {
    86→  retrieve,
    87→  retrieveByCategory,
    88→  retrieveForOccasion,
    89→  retrieveMultiQuery,
    90→  quickSearch,
    91→  normalizeQuery,
    92→  detectQueryLanguage,
    93→  extractFiltersFromQuery,
    94→} from './retrieval';
    95→
    96→// Prompt builder exports
    97→export {
    98→  formatDocumentsAsContext,
    99→  buildEnhancedPrompt,
   100→  buildFashionContext,
   101→  buildMinimalContext,
   102→  buildFollowUpContext,
   103→  getContextStats,
   104→} from './prompt-builder';
   105→
   106→// Import for RAGService class
   107→import { getRAGConfig, validateRAGConfig, getAllCategories } from './config';
   108→import {
   109→  initializeVectorStore,
   110→  getVectorStoreStats,
   111→  closeVectorStore,
   112→  isVectorStoreInitialized,
   113→} from './vector-store';
   114→import {
   115→  indexDocument,
   116→  indexDocuments,
   117→  removeDocument,
   118→  getKnowledgeBaseStats,
   119→  clearKnowledgeBase,
   120→  createKnowledgeDocument,
   121→} from './knowledge-base';
   122→import {
   123→  retrieve,
   124→  retrieveByCategory,
   125→  retrieveForOccasion,
   126→  quickSearch,
   127→} from './retrieval';
   128→import {
   129→  buildEnhancedPrompt,
   130→  buildFashionContext,
   131→  formatDocumentsAsContext,
   132→} from './prompt-builder';
   133→import { clearEmbeddingCache } from './embeddings';
   134→import type {
   135→  KnowledgeDocument,
   136→  KnowledgeCategory,
   137→  RetrievalOptions,
   138→  RetrievalResult,
   139→  RAGServiceConfig,
   140→  RAGServiceStats,
   141→} from './types';
   142→
   143→/**
   144→ * RAGService - Unified interface for the RAG system
   145→ *
   146→ * Provides a high-level API for common RAG operations including
   147→ * initialization, indexing, retrieval, and prompt enhancement.
   148→ */
   149→export class RAGService {
   150→  private initialized: boolean = false;
   151→
   152→  /**
   153→   * Initialize the RAG service
   154→   *
   155→   * @returns Promise resolving to initialization success status
   156→   */
   157→  async initialize(): Promise<boolean> {
   158→    if (this.initialized) {
   159→      return true;
   160→    }
   161→
   162→    // Validate configuration
   163→    const configValidation = validateRAGConfig();
   164→    if (!configValidation.valid) {
   165→      console.error('[RAGService] Configuration errors:', configValidation.errors);
   166→      return false;
   167→    }
   168→
   169→    // Initialize vector store
   170→    const storeInitialized = await initializeVectorStore();
   171→    if (!storeInitialized) {
   172→      console.error('[RAGService] Failed to initialize vector store');
   173→      return false;
   174→    }
   175→
   176→    this.initialized = true;
   177→    console.log('[RAGService] Initialized successfully');
   178→    return true;
   179→  }
   180→
   181→  /**
   182→   * Check if service is initialized
   183→   */
   184→  isInitialized(): boolean {
   185→    return this.initialized && isVectorStoreInitialized();
   186→  }
   187→
   188→  /**
   189→   * Get service configuration
   190→   */
   191→  getConfig(): RAGServiceConfig {
   192→    const config = getRAGConfig();
   193→    return {
   194→      isInitialized: this.initialized,
   195→      vectorStorePath: config.vectorStore.path,
   196→      indexName: config.vectorStore.indexName,
   197→      embeddingModel: config.embedding.model,
   198→      embeddingDimensions: config.embedding.dimensions,
   199→    };
   200→  }
   201→
   202→  /**
   203→   * Get service statistics
   204→   */
   205→  async getStats(): Promise<RAGServiceStats> {
   206→    const kbStats = await getKnowledgeBaseStats();
   207→    const vsStats = await getVectorStoreStats();
   208→
   209→    return {
   210→      documentCount: vsStats.documentCount,
   211→      chunkCount: kbStats.totalChunks,
   212→      categories: getAllCategories(),
   213→      lastUpdated: kbStats.lastUpdated,
   214→      indexSizeBytes: 0, // Would need file system access to calculate
   215→    };
   216→  }
   217→
   218→  /**
   219→   * Index a single knowledge document
   220→   */
   221→  async index(document: KnowledgeDocument): Promise<number> {
   222→    await this.ensureInitialized();
   223→    return indexDocument(document);
   224→  }
   225→
   226→  /**
   227→   * Index multiple knowledge documents
   228→   */
   229→  async indexBatch(documents: KnowledgeDocument[]): Promise<number> {
   230→    await this.ensureInitialized();
   231→    return indexDocuments(documents);
   232→  }
   233→
   234→  /**
   235→   * Remove a document from the index
   236→   */
   237→  async remove(documentId: string): Promise<number> {
   238→    await this.ensureInitialized();
   239→    return removeDocument(documentId);
   240→  }
   241→
   242→  /**
   243→   * Retrieve relevant knowledge for a query
   244→   */
   245→  async retrieve(query: string, options?: RetrievalOptions): Promise<RetrievalResult> {
   246→    await this.ensureInitialized();
   247→    return retrieve(query, options);
   248→  }
   249→
   250→  /**
   251→   * Retrieve by specific category
   252→   */
   253→  async retrieveByCategory(
   254→    query: string,
   255→    category: KnowledgeCategory,
   256→    options?: Omit<RetrievalOptions, 'filters'>
   257→  ): Promise<RetrievalResult> {
   258→    await this.ensureInitialized();
   259→    return retrieveByCategory(query, category, options);
   260→  }
   261→
   262→  /**
   263→   * Retrieve for a specific occasion
   264→   */
   265→  async retrieveForOccasion(
   266→    query: string,
   267→    occasion: string,
   268→    options?: Omit<RetrievalOptions, 'filters'>
   269→  ): Promise<RetrievalResult> {
   270→    await this.ensureInitialized();
   271→    return retrieveForOccasion(query, occasion, options);
   272→  }
   273→
   274→  /**
   275→   * Quick search with lower threshold
   276→   */
   277→  async quickSearch(query: string): Promise<RetrievalResult> {
   278→    await this.ensureInitialized();
   279→    return quickSearch(query);
   280→  }
   281→
   282→  /**
   283→   * Build an enhanced prompt with retrieved knowledge
   284→   */
   285→  async enhancePrompt(
   286→    basePrompt: string,
   287→    query: string,
   288→    options?: RetrievalOptions
   289→  ): Promise<string> {
   290→    const retrievalResult = await this.retrieve(query, options);
   291→    return buildEnhancedPrompt(basePrompt, retrievalResult);
   292→  }
   293→
   294→  /**
   295→   * Build fashion-specific context for a query
   296→   */
   297→  async buildContext(query: string, options?: RetrievalOptions): Promise<string> {
   298→    const retrievalResult = await this.retrieve(query, options);
   299→    return buildFashionContext(retrievalResult, query);
   300→  }
   301→
   302→  /**
   303→   * Format retrieved documents as context
   304→   */
   305→  formatAsContext(
   306→    retrievalResult: RetrievalResult,
   307→    maxTokens?: number
   308→  ): { context: string; tokenCount: number } {
   309→    const formatted = formatDocumentsAsContext(
   310→      retrievalResult.documents,
   311→      retrievalResult.scores,
   312→      maxTokens
   313→    );
   314→    return {
   315→      context: formatted.context,
   316→      tokenCount: formatted.tokenCount,
   317→    };
   318→  }
   319→
   320→  /**
   321→   * Create a knowledge document from raw data
   322→   */
   323→  createDocument(data: Parameters<typeof createKnowledgeDocument>[0]): KnowledgeDocument {
   324→    return createKnowledgeDocument(data);
   325→  }
   326→
   327→  /**
   328→   * Clear all indexed documents
   329→   */
   330→  async clearAll(): Promise<number> {
   331→    await this.ensureInitialized();
   332→    const count = await clearKnowledgeBase();
   333→    clearEmbeddingCache();
   334→    return count;
   335→  }
   336→
   337→  /**
   338→   * Close the service and release resources
   339→   */
   340→  async close(): Promise<void> {
   341→    await closeVectorStore();
   342→    clearEmbeddingCache();
   343→    this.initialized = false;
   344→    console.log('[RAGService] Closed');
   345→  }
   346→
   347→  /**
   348→   * Ensure service is initialized before operations
   349→   */
   350→  private async ensureInitialized(): Promise<void> {
   351→    if (!this.initialized) {
   352→      const success = await this.initialize();
   353→      if (!success) {
   354→        throw new Error('RAGService failed to initialize');
   355→      }
   356→    }
   357→  }
   358→}
