   360→/**
   361→ * Default RAG service instance
   362→ */
   363→let defaultInstance: RAGService | null = null;
   364→
   365→/**
   366→ * Get the default RAG service instance (singleton)
   367→ */
   368→export function getRAGService(): RAGService {
   369→  if (!defaultInstance) {
   370→    defaultInstance = new RAGService();
   371→  }
   372→  return defaultInstance;
   373→}
   374→
   375→/**
   376→ * Create a new RAG service instance
   377→ */
   378→export function createRAGService(): RAGService {
   379→  return new RAGService();
   380→}
   381→
   382→export default RAGService;
