   152→/**
   153→ * Extract corresponding Thai content for a chunk (simplified approach)
   154→ */
   155→function extractThaiChunkContent(
   156→  thaiContent: string,
   157→  chunkIndex: number,
   158→  totalChunks: number
   159→): string | undefined {
   160→  if (!thaiContent) return undefined;
   161→
   162→  const thaiSentences = splitIntoSentences(thaiContent);
   163→  if (thaiSentences.length === 0) return undefined;
   164→
   165→  // Proportional extraction
   166→  const sentencesPerChunk = Math.ceil(thaiSentences.length / Math.max(totalChunks, 1));
   167→  const startIdx = chunkIndex * sentencesPerChunk;
   168→  const endIdx = Math.min(startIdx + sentencesPerChunk, thaiSentences.length);
   169→
   170→  return thaiSentences.slice(startIdx, endIdx).join(' ') || undefined;
   171→}
