   203→    );
   204→  }
   205→
   206→  // Create vector store entries
   207→  const entries: VectorStoreEntry[] = [];
   208→
   209→  for (let i = 0; i < chunks.length && i < embeddingResult.embeddings.length; i++) {
   210→    const chunk = chunks[i];
   211→    const embedding = embeddingResult.embeddings[i];
   212→
   213→    entries.push({
   214→      id: chunk.id,
   215→      vector: embedding,
   216→      metadata: {
   217→        documentId: chunk.documentId,
   218→        chunkIndex: chunk.chunkIndex,
   219→        category: document.category,
   220→        title: document.title,
   221→        topics: chunk.metadata.topics,
   222→        occasions: chunk.metadata.occasions,
   223→        gender: chunk.metadata.gender,
   224→        seasonality: chunk.metadata.seasonality,
   225→        lastUpdated: chunk.metadata.lastUpdated,
   226→        tokenCount: chunk.tokenCount,
   227→      },
   228→      text: chunk.content,
   229→    });
   230→  }
   231→
   232→  // Add to vector store
   233→  await addDocuments(entries);
   234→
   235→  if (config.logging.debug) {
   236→    console.log(`[KnowledgeBase] Indexed ${entries.length} chunks for document ${document.id}`);
   237→  }
   238→
   239→  return entries.length;
   240→}
