   425→/**
   426→ * Estimate storage requirements for a document
   427→ *
   428→ * @param document - Document to estimate
   429→ * @returns Estimated storage in bytes
   430→ */
   431→export function estimateDocumentStorage(document: KnowledgeDocument): {
   432→  estimatedChunks: number;
   433→  estimatedTokens: number;
   434→  estimatedBytes: number;
   435→} {
   436→  const config = getRAGConfig();
   437→  const contentTokens = estimateTokenCount(document.content);
   438→  const thaiTokens = document.contentThai ? estimateTokenCount(document.contentThai) : 0;
   439→  const totalTokens = contentTokens + thaiTokens;
   440→
   441→  const estimatedChunks = Math.ceil(contentTokens / config.chunking.targetTokens);
